#include "mdl_flex_metadata_stream.h"
#include <sstream>
#include <fstream>
#include <chrono>
#include <iostream>
static void put(std::vector<uint8_t>&b,size_t p,uint32_t v){std::memcpy(b.data()+p,&v,4);}
static void equal(const std::vector<MdlFlexControllerMetadata>&a,const std::vector<MdlFlexControllerMetadata>&b){if(a.size()!=b.size())throw std::runtime_error("metadata count");for(size_t i=0;i<a.size();++i){const auto&x=a[i];const auto&y=b[i];if(x.localIndex!=y.localIndex||x.name!=y.name||x.type!=y.type||x.diskGlobalIndex!=y.diskGlobalIndex||x.minBits!=y.minBits||x.maxBits!=y.maxBits)throw std::runtime_error("metadata fields");}}
static void check(const std::vector<uint8_t>&bytes){bool oldFailed=false,newFailed=false;std::vector<MdlFlexControllerMetadata>a,b;try{a=readMdl49FlexMetadata(bytes);}catch(const std::runtime_error&){oldFailed=true;}std::string text(reinterpret_cast<const char*>(bytes.data()),bytes.size());std::istringstream stream(text,std::ios::binary);try{b=readMdl49FlexMetadataStream(stream);}catch(const std::runtime_error&){newFailed=true;}if(oldFailed!=newFailed)throw std::runtime_error("acceptance mismatch");if(!oldFailed)equal(a,b);}
int main(int argc,char**argv){try{static_assert(sizeof(void*)==8,"x64 required");if(argc>2)throw std::runtime_error("optional asset path");std::vector<uint8_t>base(16400);put(base,0,0x54534449);put(base,4,49);put(base,76,uint32_t(base.size()));put(base,268,1);put(base,272,4090);put(base,4090,uint32_t(-100));put(base,4094,4100);put(base,4098,0xffffffff);put(base,4102,0x80000000);put(base,4106,0x7f812345);base[3990]='t';for(size_t i=8190;i<8230;++i)base[i]='n';check(base);
 for(unsigned c=0;c<10;++c){auto b=base;switch(c){case 0:b.resize(200);break;case 1:put(b,0,0);break;case 2:put(b,4,48);break;case 3:put(b,76,16399);break;case 4:put(b,268,0xffffffff);break;case 5:put(b,272,16399);break;case 6:put(b,4094,0x80000000);break;case 7:put(b,4094,12309);b.back()='x';break;case 8:put(b,268,0);put(b,272,0xffffffff);break;case 9:put(b,4094,uint32_t(-100));break;}check(b);}
 uint32_t state=0x6ac12f09;for(unsigned c=0;c<400;++c){auto b=base;state=state*1664525u+1013904223u;size_t position=(c&1)?size_t(state%408):size_t(408+state%(b.size()-408));b[position]^=uint8_t(1u<<((state>>24)&7));check(b);}
 std::cout<<"stream MDL metadata: page-crossing table/string, negative offsets, ten cases and 400 mutations match full parser\n";
 if(argc==2){double full=0,paged=0;uint64_t fileBytes=0,readBytes=0;size_t controllers=0;for(unsigned trial=0;trial<3;++trial){auto start=std::chrono::steady_clock::now();std::ifstream f(argv[1],std::ios::binary);if(!f)throw std::runtime_error("asset unavailable");std::vector<uint8_t>bytes((std::istreambuf_iterator<char>(f)),{});auto expected=readMdl49FlexMetadata(bytes);auto end=std::chrono::steady_clock::now();full+=std::chrono::duration<double,std::milli>(end-start).count();fileBytes=bytes.size();start=std::chrono::steady_clock::now();std::ifstream in(argv[1],std::ios::binary);auto actual=readMdl49FlexMetadataStream(in,&readBytes);end=std::chrono::steady_clock::now();paged+=std::chrono::duration<double,std::milli>(end-start).count();equal(expected,actual);controllers=actual.size();}std::cout<<"controllers="<<controllers<<" full_file_bytes="<<fileBytes<<" paged_read_bytes="<<readBytes<<" full_mean_ms="<<full/3<<" paged_mean_ms="<<paged/3<<" trials=3 disk_cache_effects=present\n";}
 return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
